/**
 * JSON validator utility that reads from stdin and validates JSON format.
 */

async function readStdin(): Promise<string> {
  const chunks: Uint8Array[] = [];

  for await (const chunk of Bun.stdin.stream()) {
    chunks.push(chunk);
  }

  const buffer = Buffer.concat(chunks);
  return buffer.toString('utf-8');
}

export async function validateJson(input: string): Promise<{ valid: boolean; error?: string; data?: unknown }> {
  try {
    const parsed = JSON.parse(input);
    return { valid: true, data: parsed };
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown parsing error';
    return { valid: false, error: `Invalid JSON: ${message}` };
  }
}

async function main() {
  const input = await readStdin();

  if (input.trim() === '') {
    console.error('Error: No input provided via stdin');
    process.exit(1);
  }

  const result = await validateJson(input);

  if (result.valid) {
    console.log('✓ Valid JSON');
    console.log(JSON.stringify(result.data, null, 2));
    process.exit(0);
  } else {
    console.error('✗ ' + result.error);
    process.exit(1);
  }
}

if (import.meta.main) {
  main();
}

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("validates valid JSON object", async () => {
    const input = '{"test": true, "value": 123}';
    const result = await validateJson(input);

    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ test: true, value: 123 });
    expect(result.error).toBeUndefined();
  });

  test("validates valid JSON array", async () => {
    const input = '[1, 2, 3, "four"]';
    const result = await validateJson(input);

    expect(result.valid).toBe(true);
    expect(result.data).toEqual([1, 2, 3, "four"]);
  });

  test("validates valid JSON primitives", async () => {
    const stringResult = await validateJson('"hello"');
    expect(stringResult.valid).toBe(true);
    expect(stringResult.data).toBe("hello");

    const numberResult = await validateJson('42');
    expect(numberResult.valid).toBe(true);
    expect(numberResult.data).toBe(42);

    const boolResult = await validateJson('true');
    expect(boolResult.valid).toBe(true);
    expect(boolResult.data).toBe(true);

    const nullResult = await validateJson('null');
    expect(nullResult.valid).toBe(true);
    expect(nullResult.data).toBe(null);
  });

  test("rejects invalid JSON with descriptive error", async () => {
    const input = '{invalid json}';
    const result = await validateJson(input);

    expect(result.valid).toBe(false);
    expect(result.error).toContain("Invalid JSON");
    expect(result.data).toBeUndefined();
  });

  test("rejects malformed JSON with descriptive error", async () => {
    const input = '{"unclosed": "object"';
    const result = await validateJson(input);

    expect(result.valid).toBe(false);
    expect(result.error).toContain("Invalid JSON");
  });

  test("rejects empty string", async () => {
    const input = '';
    const result = await validateJson(input);

    expect(result.valid).toBe(false);
    expect(result.error).toContain("Invalid JSON");
  });

  test("handles nested complex JSON", async () => {
    const input = '{"users": [{"name": "Alice", "age": 30}, {"name": "Bob", "age": 25}], "count": 2}';
    const result = await validateJson(input);

    expect(result.valid).toBe(true);
    expect(result.data).toEqual({
      users: [
        { name: "Alice", age: 30 },
        { name: "Bob", age: 25 }
      ],
      count: 2
    });
  });
});

