export interface SchemaValidationOptions {
  schema?: JSONSchema;
  strict?: boolean;
}

export interface JSONSchema {
  type?: string | string[];
  properties?: Record<string, JSONSchema>;
  required?: string[];
  items?: JSONSchema;
  minLength?: number;
  maxLength?: number;
  minimum?: number;
  maximum?: number;
  pattern?: string;
  enum?: unknown[];
}

/**
 * Validate JSON string using Bun's native parser.
 */
export function validateJSON(input: string, options?: SchemaValidationOptions): ValidationResult {
  try {
    const data = JSON.parse(input);

    if (options?.schema) {
      const schemaResult = validateSchema(data, options.schema);
      if (!schemaResult.valid) {
        return schemaResult;
      }
    }

    return { valid: true, data };
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Invalid JSON';
    return { valid: false, error: message };
  }
}

/**
 * Validate JSON from a file with streaming support for large files.
 */
export async function validateJSONFile(filePath: string, options?: SchemaValidationOptions): Promise<ValidationResult> {
  try {
    const file = Bun.file(filePath);
    const text = await file.text();
    return validateJSON(text, options);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to read file';
    return { valid: false, error: message };
  }
}

/**
 * Validate data against a JSON schema.
 */
export function validateSchema(data: unknown, schema: JSONSchema, path: string = '$'): ValidationResult {
  if (schema.type) {
    const types = Array.isArray(schema.type) ? schema.type : [schema.type];
    const dataType = getJSONType(data);

    if (!types.includes(dataType)) {
      return {
        valid: false,
        error: `Type mismatch: expected ${types.join(' or ')}, got ${dataType}`,
        errorPath: path
      };
    }
  }

  if (schema.enum) {
    if (!schema.enum.includes(data)) {
      return {
        valid: false,
        error: `Value not in enum: ${JSON.stringify(data)}`,
        errorPath: path
      };
    }
  }

  if (typeof data === 'string') {
    if (schema.minLength !== undefined && data.length < schema.minLength) {
      return {
        valid: false,
        error: `String too short: ${data.length} < ${schema.minLength}`,
        errorPath: path
      };
    }

    if (schema.maxLength !== undefined && data.length > schema.maxLength) {
      return {
        valid: false,
        error: `String too long: ${data.length} > ${schema.maxLength}`,
        errorPath: path
      };
    }

    if (schema.pattern) {
      const regex = new RegExp(schema.pattern);
      if (!regex.test(data)) {
        return {
          valid: false,
          error: `String does not match pattern: ${schema.pattern}`,
          errorPath: path
        };
      }
    }
  }

  if (typeof data === 'number') {
    if (schema.minimum !== undefined && data < schema.minimum) {
      return {
        valid: false,
        error: `Number too small: ${data} < ${schema.minimum}`,
        errorPath: path
      };
    }

    if (schema.maximum !== undefined && data > schema.maximum) {
      return {
        valid: false,
        error: `Number too large: ${data} > ${schema.maximum}`,
        errorPath: path
      };
    }
  }

  if (data !== null && typeof data === 'object') {
    if (Array.isArray(data)) {
      if (schema.items) {
        for (let i = 0; i < data.length; i++) {
          const result = validateSchema(data[i], schema.items, `${path}[${i}]`);
          if (!result.valid) {
            return result;
          }
        }
      }
    } else {
      if (schema.properties) {
        for (const [key, propSchema] of Object.entries(schema.properties)) {
          if (key in data) {
            const result = validateSchema((data as Record<string, unknown>)[key], propSchema, `${path}.${key}`);
            if (!result.valid) {
              return result;
            }
          }
        }
      }

      if (schema.required) {
        for (const requiredKey of schema.required) {
          if (!(requiredKey in data)) {
            return {
              valid: false,
              error: `Missing required property: ${requiredKey}`,
              errorPath: path
            };
          }
        }
      }
    }
  }

  return { valid: true, data };
}

/**
 * Get JSON type of a value.
 */
function getJSONType(value: unknown): string {
  if (value === null) {
    return 'null';
  }
  if (Array.isArray(value)) {
    return 'array';
  }
  return typeof value;
}

/**
 * CLI interface for JSON validation.
 */
export async function runCLI(args: string[]): Promise<number> {
  if (args.length === 0) {
    console.error('Usage: bun run src/validate-json.ts <file> [--schema <schema-file>]');
    return 1;
  }

  const filePath = args[0];
  let schemaPath: string | undefined;

  const schemaIndex = args.indexOf('--schema');
  if (schemaIndex !== -1 && args[schemaIndex + 1]) {
    schemaPath = args[schemaIndex + 1];
  }

  let schema: JSONSchema | undefined;
  if (schemaPath) {
    try {
      const schemaFile = Bun.file(schemaPath);
      const schemaText = await schemaFile.text();
      schema = JSON.parse(schemaText);
    } catch (error) {
      console.error(`Failed to load schema: ${error instanceof Error ? error.message : 'Unknown error'}`);
      return 1;
    }
  }

  const result = await validateJSONFile(filePath, { schema });

  if (result.valid) {
    console.log('✓ Valid JSON');
    return 0;
  } else {
    console.error('✗ Invalid JSON');
    console.error(`  Error: ${result.error}`);
    if (result.errorPath) {
      console.error(`  Path: ${result.errorPath}`);
    }
    return 1;
  }
}

if (import.meta.main) {
  const exitCode = await runCLI(process.argv.slice(2));
  process.exit(exitCode);
}

import { describe, expect, test } from "bun:test";
import { validateJSON, validateJSONFile, validateSchema, runCLI } from "./validate-json";
import { writeFileSync, unlinkSync, mkdtempSync } from "fs";
import { join } from "path";
import { tmpdir } from "os";

describe("validateJSON", () => {
  test("validates valid JSON string", () => {
    const result = validateJSON('{"key": "value"}');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ key: "value" });
  });

  test("rejects invalid JSON string", () => {
    const result = validateJSON('{invalid}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("validates arrays", () => {
    const result = validateJSON('[1, 2, 3]');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual([1, 2, 3]);
  });

  test("validates primitives", () => {
    expect(validateJSON('"string"').valid).toBe(true);
    expect(validateJSON('123').valid).toBe(true);
    expect(validateJSON('true').valid).toBe(true);
    expect(validateJSON('null').valid).toBe(true);
  });

  test("handles empty objects and arrays", () => {
    expect(validateJSON('{}').valid).toBe(true);
    expect(validateJSON('[]').valid).toBe(true);
  });
});

describe("validateJSONFile", () => {
  const tempDir = mkdtempSync(join(tmpdir(), "json-test-"));
  const validFile = join(tempDir, "valid.json");
  const invalidFile = join(tempDir, "invalid.json");

  writeFileSync(validFile, '{"test": true}');
  writeFileSync(invalidFile, '{not valid json}');

  test("validates valid JSON file", async () => {
    const result = await validateJSONFile(validFile);
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ test: true });
  });

  test("rejects invalid JSON file", async () => {
    const result = await validateJSONFile(invalidFile);
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("handles missing file", async () => {
    const result = await validateJSONFile(join(tempDir, "nonexistent.json"));
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });
});

describe("validateSchema", () => {
  test("validates type constraints", () => {
    expect(validateSchema("test", { type: "string" }).valid).toBe(true);
    expect(validateSchema(123, { type: "number" }).valid).toBe(true);
    expect(validateSchema(true, { type: "boolean" }).valid).toBe(true);
    expect(validateSchema(null, { type: "null" }).valid).toBe(true);
    expect(validateSchema([], { type: "array" }).valid).toBe(true);
    expect(validateSchema({}, { type: "object" }).valid).toBe(true);
  });

  test("rejects type mismatches with error path", () => {
    const result = validateSchema("test", { type: "number" });
    expect(result.valid).toBe(false);
    expect(result.error).toContain("Type mismatch");
    expect(result.errorPath).toBe("$");
  });

  test("supports multiple types", () => {
    expect(validateSchema("test", { type: ["string", "number"] }).valid).toBe(true);
    expect(validateSchema(123, { type: ["string", "number"] }).valid).toBe(true);
    expect(validateSchema(true, { type: ["string", "number"] }).valid).toBe(false);
  });

  test("validates required properties", () => {
    const schema = {
      type: "object" as const,
      required: ["name", "age"]
    };

    expect(validateSchema({ name: "John", age: 30 }, schema).valid).toBe(true);

    const result = validateSchema({ name: "John" }, schema);
    expect(result.valid).toBe(false);
    expect(result.error).toContain("Missing required property: age");
  });

  test("validates nested object properties", () => {
    const schema = {
      type: "object" as const,
      properties: {
        name: { type: "string" as const },
        age: { type: "number" as const }
      }
    };

    expect(validateSchema({ name: "John", age: 30 }, schema).valid).toBe(true);

    const result = validateSchema({ name: "John", age: "thirty" }, schema);
    expect(result.valid).toBe(false);
    expect(result.errorPath).toBe("$.age");
  });

  test("validates array items", () => {
    const schema = {
      type: "array" as const,
      items: { type: "number" as const }
    };

    expect(validateSchema([1, 2, 3], schema).valid).toBe(true);

    const result = validateSchema([1, "two", 3], schema);
    expect(result.valid).toBe(false);
    expect(result.errorPath).toBe("$[1]");
  });

  test("validates string length constraints", () => {
    expect(validateSchema("test", { type: "string", minLength: 2, maxLength: 10 }).valid).toBe(true);
    expect(validateSchema("x", { type: "string", minLength: 2 }).valid).toBe(false);
    expect(validateSchema("very long string", { type: "string", maxLength: 5 }).valid).toBe(false);
  });

  test("validates string patterns", () => {
    const emailSchema = { type: "string" as const, pattern: "^[^@]+@[^@]+\\.[^@]+$" };

    expect(validateSchema("user@example.com", emailSchema).valid).toBe(true);
    expect(validateSchema("invalid", emailSchema).valid).toBe(false);
  });

  test("validates number range constraints", () => {
    expect(validateSchema(5, { type: "number", minimum: 0, maximum: 10 }).valid).toBe(true);
    expect(validateSchema(-1, { type: "number", minimum: 0 }).valid).toBe(false);
    expect(validateSchema(11, { type: "number", maximum: 10 }).valid).toBe(false);
  });

  test("validates enum constraints", () => {
    const schema = { type: "string" as const, enum: ["red", "green", "blue"] };

    expect(validateSchema("red", schema).valid).toBe(true);
    expect(validateSchema("yellow", schema).valid).toBe(false);
  });

  test("validates complex nested structures", () => {
    const schema = {
      type: "object" as const,
      required: ["users"],
      properties: {
        users: {
          type: "array" as const,
          items: {
            type: "object" as const,
            required: ["id", "email"],
            properties: {
              id: { type: "number" as const },
              email: { type: "string" as const, pattern: "^[^@]+@[^@]+\\.[^@]+$" }
            }
          }
        }
      }
    };

    const validData = {
      users: [
        { id: 1, email: "user1@example.com" },
        { id: 2, email: "user2@example.com" }
      ]
    };

    expect(validateSchema(validData, schema).valid).toBe(true);

    const invalidData = {
      users: [
        { id: 1, email: "invalid-email" }
      ]
    };

    const result = validateSchema(invalidData, schema);
    expect(result.valid).toBe(false);
    expect(result.errorPath).toBe("$.users[0].email");
  });
});

describe("runCLI", () => {
  const tempDir = mkdtempSync(join(tmpdir(), "cli-test-"));
  const validFile = join(tempDir, "valid.json");
  const invalidFile = join(tempDir, "invalid.json");
  const schemaFile = join(tempDir, "schema.json");

  writeFileSync(validFile, '{"name": "test", "age": 25}');
  writeFileSync(invalidFile, '{invalid}');
  writeFileSync(schemaFile, JSON.stringify({
    type: "object",
    required: ["name", "age"],
    properties: {
      name: { type: "string" },
      age: { type: "number" }
    }
  }));

  test("validates file without schema", async () => {
    const exitCode = await runCLI([validFile]);
    expect(exitCode).toBe(0);
  });

  test("validates file with schema", async () => {
    const exitCode = await runCLI([validFile, "--schema", schemaFile]);
    expect(exitCode).toBe(0);
  });

  test("returns error for invalid JSON", async () => {
    const exitCode = await runCLI([invalidFile]);
    expect(exitCode).toBe(1);
  });

  test("returns error for missing arguments", async () => {
    const exitCode = await runCLI([]);
    expect(exitCode).toBe(1);
  });
});

describe("performance benchmarks", () => {
  test("validates small JSON objects quickly", () => {
    const data = '{"key": "value"}';
    const iterations = 10000;

    const start = performance.now();
    for (let i = 0; i < iterations; i++) {
      validateJSON(data);
    }
    const duration = performance.now() - start;

    expect(duration).toBeLessThan(100);
  });

  test("validates medium JSON objects efficiently", () => {
    const data = JSON.stringify({
      users: Array.from({ length: 100 }, (_, i) => ({
        id: i,
        name: `User ${i}`,
        email: `user${i}@example.com`,
        active: i % 2 === 0
      }))
    });
    const iterations = 1000;

    const start = performance.now();
    for (let i = 0; i < iterations; i++) {
      validateJSON(data);
    }
    const duration = performance.now() - start;

    expect(duration).toBeLessThan(500);
  });

  test("validates with schema efficiently", () => {
    const data = { name: "test", age: 25, email: "test@example.com" };
    const schema = {
      type: "object" as const,
      required: ["name", "age"],
      properties: {
        name: { type: "string" as const },
        age: { type: "number" as const },
        email: { type: "string" as const, pattern: "^[^@]+@[^@]+\\.[^@]+$" }
      }
    };
    const iterations = 10000;

    const start = performance.now();
    for (let i = 0; i < iterations; i++) {
      validateSchema(data, schema);
    }
    const duration = performance.now() - start;

    expect(duration).toBeLessThan(100);
  });

  test("handles large arrays efficiently", () => {
    const largeArray = Array.from({ length: 1000 }, (_, i) => i);
    const data = JSON.stringify(largeArray);
    const iterations = 100;

    const start = performance.now();
    for (let i = 0; i < iterations; i++) {
      validateJSON(data);
    }
    const duration = performance.now() - start;

    expect(duration).toBeLessThan(200);
  });
});

